(()=>{const e=document.getElementById("research-image-viewer");if(!e||typeof e.showModal!="function")return;const t=e.querySelector(".image-viewer-image"),o=e.querySelector("#image-viewer-title"),n=e.querySelector(".image-viewer-original"),i=e.querySelector(".image-viewer-close");let s;document.querySelectorAll("[data-image-preview]").forEach(i=>{i.addEventListener("click",a=>{if(a.button!==0||a.metaKey||a.ctrlKey||a.shiftKey||a.altKey)return;a.preventDefault(),s=i,o.textContent=i.dataset.imageTitle,t.alt=`Enlarged image for: ${i.dataset.imageTitle}`,t.src=i.href,n.href=i.href,e.showModal(),document.documentElement.classList.add("image-viewer-open")})}),i.addEventListener("click",()=>e.close()),e.addEventListener("click",t=>{if(t.target!==e)return;const n=e.getBoundingClientRect();(t.clientX<n.left||t.clientX>n.right||t.clientY<n.top||t.clientY>n.bottom)&&e.close()}),e.addEventListener("close",()=>{document.documentElement.classList.remove("image-viewer-open"),t.removeAttribute("src"),n.removeAttribute("href"),s?.focus({preventScroll:!0})})})()